if(!exists('simulate_trade_receivables'))library(creditratingsystem)
spa_D<-'2023-01-01';spa_dates<-list('2023-07-01','2024-01-01')
spa_asset<-function(id='a',group='g')list(asset_id=id,asset_class='AUTO_LOAN',invoice_id=NULL,obligor_id=group,default_group_id=group,seller_id='seller',servicer_id='service',currency='EUR',observed_at=spa_D,known_at=spa_D,origination_date='2022-01-01',balance_date=spa_D,principal_balance=100,schedule=list(list(date=spa_dates[[1]],principal_due=40,interest_due=5),list(date=spa_dates[[2]],principal_due=60,interest_due=3)),overdue_days=0,disputed=FALSE,dilution_reserve=0,recourse='NONE',collateral_allocations=list())
spa_assignment<-function(id='m',aid='a',start=spa_D,price=100)list(assignment_id=id,pool_id='pool',asset_id=aid,known_at=spa_D,effective_from=start,effective_until=NULL,share=1,purchase_price=price,purchase_priority=1)
spa_fixture<-function(assets=list(spa_asset()),assignments=list(spa_assignment()),revolving=FALSE){
 p<-list(profile_id='p',version='1',known_at=spa_D,currency='EUR',product_kind='ABS',pool_mode=if(revolving)'REVOLVING'else'STATIC',allowed_asset_classes=list('AUTO_LOAN'),maximum_dpd=30,exclude_disputed=TRUE,eligible_recourse=list('NONE'),revolving_until=if(revolving)spa_dates[[2]]else NULL)
 pool<-build_credit_asset_pool(assets,assignments,p,'pool',spa_D,spa_D)$value
 contract<-list(contract_id='c',version='1',scenario_ids=list('s'),weights=list(1),dates=spa_dates,currency='EUR',probability_measure='PHYSICAL',sampling_design='FIXED_WEIGHTED_SCENARIOS',conditioning='PIT',default_timing='BEFORE_DUE',prepayment_timing='AFTER_COUPON',dilution_treatment='PROPORTIONAL_REMAINING_SCHEDULE',reinvestment_funding='PRINCIPAL_CASH_ONLY',initial_reinvestment_cash=0)
 gp<-ap<-innov<-list();for(g in sort(unique(vapply(assets,function(a)a$default_group_id,''))))for(d in spa_dates){gp[[length(gp)+1L]]<-list(scenario_id='s',default_group_id=g,date=d,conditional_pd=0,default_channel=paste0('default-',g));innov[[length(innov)+1L]]<-list(scenario_id='s',date=d,channel_id=paste0('default-',g),uniform=.5)}
 for(a in assets)for(d in spa_dates){ap[[length(ap)+1L]]<-list(scenario_id='s',asset_id=a$asset_id,date=d,conditional_prepayment_probability=0,prepayment_channel=paste0('prepay-',a$asset_id),dilution_fraction=0,recovery_fraction=.4,recovery_delay_days=30,recovery_cost=5,servicing_cost=0,interest_multiplier=1,overdue_days=0,disputed=FALSE);innov[[length(innov)+1L]]<-list(scenario_id='s',date=d,channel_id=paste0('prepay-',a$asset_id),uniform=.5)}
 list(asset_pool=pool,scenario_contract=contract,obligor_paths=gp,asset_paths=ap,shared_innovations=innov)
}
spa_run<-function(f)do.call(simulate_asset_pool,f)$value
spa_total<-function(r,key)sum(vapply(r$cashflows,function(c)c[[key]],0.))
spa_error<-function(code,expr){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}

st_dates<-list('2023-02-01','2023-03-01','2023-04-01')
st_fixture<-function(n=1,recourse='SELLER'){
 assets<-assign<-list();for(i in seq_len(n)){id<-paste0('a',i-1L);a<-spa_asset(id);a$asset_class<-'INVOICE';a$invoice_id<-paste0('i',i-1L);a$recourse<-recourse;a$schedule<-list(list(date=st_dates[[1]],principal_due=100,interest_due=0));assets[[i]]<-a;assign[[i]]<-spa_assignment(paste0('m',i-1L),id)}
 profile<-list(profile_id='invoice',version='1',known_at=spa_D,currency='EUR',product_kind='TRADE_RECEIVABLES',pool_mode='STATIC',allowed_asset_classes=list('INVOICE'),maximum_dpd=30,exclude_disputed=TRUE,eligible_recourse=list('NONE','SELLER'),revolving_until=NULL);pool<-build_credit_asset_pool(assets,assign,profile,'pool',spa_D,spa_D)$value;contract<-list(contract_id='invoice-scenarios',version='1',scenario_ids=list('s'),weights=list(1),dates=st_dates,currency='EUR',probability_measure='PHYSICAL',sampling_design='FIXED_WEIGHTED_SCENARIOS',conditioning='PIT');mapping<-lapply(c('g','seller','service'),function(g)list(party_id=g,default_group_id=g));paths<-innovations<-list();for(g in c('g','seller','service'))for(d in st_dates){paths[[length(paths)+1L]]<-list(scenario_id='s',default_group_id=g,date=d,conditional_pd=0,default_channel=g);innovations[[length(innovations)+1L]]<-list(scenario_id='s',date=d,channel_id=g,uniform=.5)};invoices<-lapply(assets,function(a)list(scenario_id='s',asset_id=a$asset_id,payment_date=st_dates[[1]],dilution_date=spa_D,dilution_fraction=0,debtor_recovery_fraction=.4,debtor_recovery_date=st_dates[[2]],debtor_recovery_cost=0));sellers<-list(list(scenario_id='s',seller_id='seller',settlement_date=st_dates[[3]],performing_capacity=1000,default_estate_capacity=20,default_recovery_fraction=.5,recourse_scope='CREDIT_ONLY'));services<-list(list(scenario_id='s',servicer_id='service',remittance_date=st_dates[[3]],default_commingling_recovery_fraction=.5,default_commingling_capacity=30,replacement_cost=5));list(invoice_pool=pool,scenario_contract=contract,party_mapping=mapping,party_default_paths=paths,invoice_scenarios=invoices,seller_terms=sellers,servicer_terms=services,shared_innovations=innovations)
}
st_run<-function(f)do.call(simulate_trade_receivables,f)$value
stopifnot(st_run(st_fixture())$ending_states[[1]]$net_investor_cash==100);f<-st_fixture(2);f$party_default_paths[[1]]$conditional_pd<-1;f$seller_terms[[1]]$performing_capacity<-50;r<-st_run(f);stopifnot(all(vapply(r$invoice_results,function(x)x$debtor_credit_event&&x$seller_credit_recourse==25,TRUE)),r$seller_results[[1]]$aggregate_payment==50,r$ending_states[[1]]$net_credit_loss==70,r$ending_states[[1]]$net_investor_cash==130,r$ending_states[[1]]$conservation_residual==0)
f<-st_fixture(2);f$party_default_paths[[1]]$conditional_pd<-1;f$party_default_paths[[4]]$conditional_pd<-1;r<-st_run(f);stopifnot(r$seller_results[[1]]$in_default,r$seller_results[[1]]$aggregate_payment==20,r$ending_states[[1]]$net_credit_loss==100);f<-st_fixture(recourse='NONE');f$party_default_paths[[1]]$conditional_pd<-1;r<-st_run(f);stopifnot(r$seller_results[[1]]$aggregate_payment==0,r$ending_states[[1]]$net_credit_loss==60)
f<-st_fixture();f$invoice_scenarios[[1]]$dilution_fraction<-1;r<-st_run(f);stopifnot(!r$invoice_results[[1]]$debtor_credit_event,r$ending_states[[1]]$net_dilution_loss==100,r$ending_states[[1]]$net_credit_loss==0);f$seller_terms[[1]]$recourse_scope<-'CREDIT_AND_DILUTION';r<-st_run(f);stopifnot(r$invoice_results[[1]]$seller_dilution_recourse==100,r$ending_states[[1]]$net_investor_cash==100)
f<-st_fixture(recourse='NONE');f$party_default_paths[[2]]$conditional_pd<-1;stopifnot(st_run(f)$ending_states[[1]]$net_credit_loss==0);f$invoice_scenarios[[1]]$payment_date<-st_dates[[2]];r<-st_run(f);stopifnot(r$invoice_results[[1]]$debtor_credit_event,r$ending_states[[1]]$net_credit_loss==60)
f<-st_fixture(2);f$party_default_paths[[8]]$conditional_pd<-1;r<-st_run(f);v<-r$servicer_results[[1]];stopifnot(v$held_cash==200,v$remittance==30,v$commingling_loss==170,v$replacement_cost==5,r$ending_states[[1]]$net_investor_cash==25,r$ending_states[[1]]$conservation_residual==0);f<-st_fixture();f$party_default_paths[[7]]$conditional_pd<-1;r<-st_run(f);v<-r$servicer_results[[1]];stopifnot(v$held_cash==0,v$redirected_cash==100,v$commingling_loss==0,r$ending_states[[1]]$net_investor_cash==95)
f<-st_fixture();f$party_mapping[[2]]$default_group_id<-'g';f$party_default_paths<-Filter(function(p)p$default_group_id!='seller',f$party_default_paths);f$shared_innovations<-Filter(function(p)p$channel_id!='seller',f$shared_innovations);f$party_default_paths[[1]]$conditional_pd<-1;f$invoice_scenarios[[1]]$debtor_recovery_cost<-5;r<-st_run(f);stopifnot(r$seller_results[[1]]$in_default,r$seller_results[[1]]$aggregate_payment==20,r$ending_states[[1]]$net_investor_cash==55,r$ending_states[[1]]$net_credit_loss==40)
f<-st_fixture();f$party_mapping[[4]]<-f$party_mapping[[1]];spa_error('STRUCTURED_DEFAULT_GROUP',st_run(f));f<-st_fixture();f$invoice_scenarios[[1]]$payment_date<-'2024-01-01';spa_error('STRUCTURED_CALENDAR',st_run(f));f<-st_fixture();f$servicer_terms[[1]]$remittance_date<-spa_D;spa_error('STRUCTURED_CALENDAR',st_run(f));f<-st_fixture();f$context<-list(horizon=1);spa_error('TARGET_MISMATCH',st_run(f))
cat('Native invoice shared default, recourse capacity and commingling oracles PASS\n')
